SELECT i.id, i.material_id, i.warehouse_id, i.current_qty, m.code AS material_code, m.del_flag AS material_del_flag, w.name AS warehouse_name, w.del_flag AS warehouse_del_flag FROM c_mes_inventory i LEFT JOIN c_mes_material m ON i.material_id = m.id LEFT JOIN c_mes_warehouse w ON i.warehouse_id = w.id WHERE (m.id IS NULL OR m.del_flag = 1 OR w.id IS NULL OR w.del_flag = 1) AND i.id IN
#{id}
FOR UPDATE
